/** Get local mannequin config by gender */
export function getLocalMannequinConfig(gender: "male" | "female"): MannequinConfig {
  return gender === "male" ? LOCAL_MANNEQUIN_CONFIG_MALE : LOCAL_MANNEQUIN_CONFIG_FEMALE
}

/**
 * Get alternatives filtered by type
 */
export function getAlternativesByType(type: "top" | "bottom" | "shoes"): LandingMockProduct[] {
  return MOCK_ALTERNATIVES.filter((p) => p.type === type)
}

/**
 * Get all alternatives
 */
export function getAllAlternatives(): LandingMockProduct[] {
  return MOCK_ALTERNATIVES
}

export function isDressProduct(product?: LandingMockProduct | null): boolean {
  return Boolean(product?.isDress)
}

/**
 * Convert a LandingMockProduct to StudioRenderedItem for use with OutfitInspirationTile
 */
export function toRenderedItem(product: LandingMockProduct): StudioRenderedItem {
  return {
    id: product.id,
    zone: product.type as StudioRenderedZone,
    imageUrl: product.imageUrl,
    placementX: product.placementX,
    placementY: product.placementY,
    imageLengthCm: product.imageLengthCm,
    brand: product.brand,
    productName: product.productName,
    price: product.price,
    currency: product.currency,
    gender: product.gender, // Pass gender through if needed
    bodyPartsVisible: product.bodyPartsVisible ?? null, // Pass through body parts visibility
    // Without this the photoreal renderer draws a bare mannequin: it only composites items that
    // carry a placement, and this mapper was the single point where it got dropped.
    placement: product.placement ?? null,
  }
}

/**
 * Get default outfit as StudioRenderedItem array
 */
export function getDefaultRenderedItems(gender: "male" | "female" = "female"): StudioRenderedItem[] {
  const outfit = gender === "male" ? MOCK_OUTFIT_ITEMS_MALE : MOCK_OUTFIT_ITEMS_FEMALE
  return [
    toRenderedItem(outfit.top),
    toRenderedItem(outfit.bottom),
    toRenderedItem(outfit.shoes),
  ]
}
